package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class InlineCycleTests {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static String runtime(Document d){FlowEngine.Runner run=new FlowEngine.Runner(d);for(int i=0;i<5000&&run.state!=FlowEngine.State.COMPLETED&&run.state!=FlowEngine.State.ERROR;i++)run.step();check(run.state==FlowEngine.State.COMPLETED,"Original graph completes: "+run.errorMessage);return run.outputText().replace("\r\n","\n");}
 static String structural(Document graph){StringBuilder s=new StringBuilder();for(Node n:graph.nodes)s.append(n.id).append(':').append(n.kind).append(':').append(n.text).append(':').append(n.x).append(':').append(n.y).append('|');for(Edge e:graph.edges)s.append(e.id).append(':').append(e.from).append(':').append(e.to).append(':').append(e.branch).append('|');return s.toString();}
 static void validate(Document graph,FlowCycleFold fold){FlowCycleFold.Projection p=fold.current;if(p==null){for(FlowCycle.Info c:fold.cycles)check(!graph.find(c.check).foldedCycle,"Null projection has no folded cycles");return;}Set<String> seen=new HashSet<>();for(Node n:p.scene.nodes)seen.add(n.id);check(seen.size()==p.scene.nodes.size(),"Scene IDs unique");for(Node n:graph.nodes)check(seen.contains(p.owner(n.id)),"Every original node represented");for(Edge e:p.scene.edges){Edge original=p.sourceEdges.get(e.id);check(e.from.equals(p.owner(original.from))&&e.to.equals(p.owner(original.to))&&seen.contains(e.from)&&seen.contains(e.to),"Actual edge identity maps to visible endpoints");}
  for(FlowCycle.Info c:p.cards.values()){check(p.selection(Arrays.asList(c.entry)).equals(c.members),"Capsule selects complete executable group");for(String id:c.members)check(p.containsActive(c.entry,id),"Every runtime step maps to capsule");Node entry=graph.find(c.entry),card=p.visual(c.entry);check(Math.abs(entry.x+width(entry)/2-card.x-width(card)/2)<.01f,"Header preserves center X");Edge out=null;for(Edge e:p.scene.edges)if(e.from.equals(c.entry))out=e;check(out!=null,"Visible cycle exit");Node target=p.visual(out.to);check(target.y+.1f>=card.y+height(card),"Downstream remains below capsule");}
 }
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] row=line.split("\t");String code=new String(Base64.getDecoder().decode(row[1]),StandardCharsets.UTF_8),expected=new String(Base64.getDecoder().decode(row[2]),StandardCharsets.UTF_8);Document document=FlowPseudocode.decode(code);String before=FlowCodec.encode(document);check(runtime(document).equals(expected),"Initial result "+row[0]);
  for(Document graph:FlowFunctionEditing.graphs(document)){String original=structural(graph);FlowCycleFold fold=new FlowCycleFold(graph);check(fold.current==null,"Default expanded");fold.all(true);validate(graph,fold);check(structural(graph).equals(original),"Fold preserves positions and executable graph");check(runtime(document).equals(expected),"Fold preserves interpreter "+row[0]);Document clone=document.copy();int flags=0,otherFlags=0;for(Document g:FlowFunctionEditing.graphs(document))for(Node n:g.nodes)if(n.foldedCycle)flags++;for(Document g:FlowFunctionEditing.graphs(clone))for(Node n:g.nodes)if(n.foldedCycle)otherFlags++;check(flags==otherFlags,"Flags survive native clone");
   if(fold.current!=null){FlowCycleFold.Projection current=fold.current;FlowCycle.Info c=current.cards.values().iterator().next();float x=current.visual(c.entry).x,y=current.visual(c.entry).y;int builds=fold.rebuilds;for(int i=0;i<1000;i++)current.sync();check(fold.rebuilds==builds,"Pointer geometry sync never recognizes cycles again");for(Node n:graph.nodes)if(c.members.contains(n.id)){n.x+=48;n.y+=24;}fold.update();check(current==fold.current&&fold.rebuilds==builds,"Move reuses current scene");check(Math.abs(current.visual(c.entry).x-x-48)<.01f&&Math.abs(current.visual(c.entry).y-y-24)<.01f,"Whole-group move remains at released position");for(Node n:graph.nodes)if(c.members.contains(n.id)){n.x-=48;n.y-=24;}fold.update();check(structural(graph).equals(original),"Restored move preserves graph");}
   FlowCycle.Info outer=null,inner=null;for(FlowCycle.Info c:fold.cycles)for(FlowCycle.Info n:fold.cycles)if(FlowCycleFold.proper(n.members,c.members)){outer=c;inner=n;break;}if(outer!=null){check(fold.current.cards.containsKey(outer.entry)&&!fold.current.cards.containsKey(inner.entry),"Outer fold owns nested cycle");fold.set(outer.check,false);check(fold.current!=null&&fold.current.cards.containsKey(inner.entry),"Unfold keeps inner presentation choice");fold.reveal(inner.bodyEntry);check(!graph.find(inner.check).foldedCycle,"Reveal original node expands enclosing folds");}
   fold.all(false);check(fold.current==null&&structural(graph).equals(original),"Expand restores original geometry");
  }
  check(FlowCodec.encode(document).equals(before),"Full fold/unfold leaves original bytes unchanged");Document load=FlowPseudocode.decode(code);for(Document graph:FlowFunctionEditing.graphs(load))new FlowCycleFold(graph).all(true);Path file=root.resolve("android-"+row[0]+".frociart");Files.write(file,FlowCodec.encode(load).getBytes(StandardCharsets.UTF_8));check(runtime(FlowCodec.decode(new String(Files.readAllBytes(file),StandardCharsets.UTF_8))).equals(expected),"Save/reopen preserves algorithm");Document pc=FlowCodec.decode(new String(Files.readAllBytes(root.resolve("pc-"+row[0]+".frociart")),StandardCharsets.UTF_8));check(runtime(pc).equals(expected),"PC project readable with folded metadata");System.out.println("PASS "+row[0]);
 }
 System.out.println("INLINE_CYCLE_ANDROID_CORE PASS checks="+checks);
 }
}
